@if($resident->activeAllocation)@push('scripts')<script>const vacate=document.getElementById('vacate-dialog'),refund=document.getElementById('refund-security-deposit'),amountField=document.querySelector('.refund-amount-field'),amount=document.querySelector('[name=refund_amount]');document.querySelector('[data-open-vacate]')?.addEventListener('click',()=>vacate.showModal());document.querySelectorAll('[data-close-vacate]').forEach(button=>button.addEventListener('click',()=>vacate.close()));function toggleRefund(){amountField.hidden=!refund.checked;amount.required=refund.checked;}refund.addEventListener('change',toggleRefund);toggleRefund();if(location.hash==='#checkout')vacate.showModal();</script>@endpush @endif
